 10	import com.pousadamarealta.database.Database;
 11	import com.pousadamarealta.database.MessageDao;
 12	import com.pousadamarealta.database.ReservationDao;
 13	import com.pousadamarealta.database.RoomDao;
 14	import com.pousadamarealta.messaging.MessagePipeline;
 15	import com.pousadamarealta.messaging.MessageRule;
 16	import com.pousadamarealta.messaging.rules.ArchiveCopyRule;
 17	import com.pousadamarealta.messaging.rules.EmailValidationRule;
 18	import com.pousadamarealta.messaging.rules.TestModeRedirectRule;
 19	import com.pousadamarealta.reports.OccupancyReport;
 20	import com.pousadamarealta.reports.RevenueReport;
 21	import com.pousadamarealta.service.MessageService;
 22	import com.pousadamarealta.service.PricingCalculator;
 23	import com.pousadamarealta.service.ReservationService;
 24	import io.javalin.Javalin;
 25	import io.javalin.json.JavalinJackson;
 26	
 27	import java.util.ArrayList;
 28	import java.util.List;
 29	
 30	public class Application {
 31	    public static void main(String[] args) {
 32	        String dbUrl = getEnv("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 33	        String dbUser = getEnv("DB_USER", "postgres");
 34	        String dbPassword = getEnv("DB_PASSWORD", "postgres");
 35	        int port = Integer.parseInt(getEnv("PORT", "7070"));
 36	        boolean testMode = "true".equalsIgnoreCase(getEnv("HOTEL_TEST_MODE", "false"));
 37	
 38	        Database database = new Database(dbUrl, dbUser, dbPassword);
 39	
 40	        RoomDao roomDao = new RoomDao(database);
 41	        ReservationDao reservationDao = new ReservationDao(database);
 42	        MessageDao messageDao = new MessageDao(database);
 43	
 44	        MessagePipeline messagePipeline = createMessagePipeline(testMode);
 45	        MessageService messageService = new MessageService(messageDao, messagePipeline);
 46	
 47	        PricingCalculator pricingCalculator = new PricingCalculator();
 48	        ReservationService reservationService = new ReservationService(
 49	            reservationDao, roomDao, pricingCalculator, messageService);
 50	
 51	        OccupancyReport occupancyReport = new OccupancyReport(reservationDao, roomDao);
 52	        RevenueReport revenueReport = new RevenueReport(reservationDao);
 53	
 54	        RoomHandler roomHandler = new RoomHandler(roomDao);
 55	        ReservationHandler reservationHandler = new ReservationHandler(reservationService, roomDao);
 56	        MessageHandler messageHandler = new MessageHandler(messageService);
 57	        ReportHandler reportHandler = new ReportHandler(occupancyReport, revenueReport);
 58	
 59	        ObjectMapper objectMapper = new ObjectMapper();
 60	        objectMapper.registerModule(new JavaTimeModule());
 61	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 62	
 63	        Javalin app = Javalin.create(config -> {
 64	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 65	        });
 66	
 67	        app.get("/rooms", roomHandler::getRooms);
 68	
 69	        app.post("/reservations", reservationHandler::createReservation);
 70	        app.get("/reservations/{id}", reservationHandler::getReservation);
 71	        app.post("/reservations/{id}/confirmation", reservationHandler::confirmReservation);
 72	        app.post("/reservations/{id}/check-in", reservationHandler::checkIn);
 73	        app.post("/reservations/{id}/check-out", reservationHandler::checkOut);
 74	        app.post("/reservations/{id}/cancellation", reservationHandler::cancelReservation);
 75	        app.get("/reservations/{id}/document", reservationHandler::getDocument);
 76	
 77	        app.get("/messages", messageHandler::getMessages);
 78	
 79	        app.get("/reports/occupancy", reportHandler::getOccupancyReport);
 80	        app.get("/reports/revenue", reportHandler::getRevenueReport);
 81	
 82	        app.start(port);
 83	
 84	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 85	            app.stop();
 86	            database.close();
 87	        }));
 88	    }
 89	
 90	    private static MessagePipeline createMessagePipeline(boolean testMode) {
 91	        List<MessageRule> rules = new ArrayList<>();
 92	
 93	        rules.add(new EmailValidationRule());
 94	
 95	        if (testMode) {
 96	            rules.add(new TestModeRedirectRule());
 97	        } else {
 98	            rules.add(new ArchiveCopyRule());
 99	        }
100	
101	        return new MessagePipeline(rules);
102	    }
103	
104	    private static String getEnv(String key, String defaultValue) {
105	        String value = System.getenv(key);
106	        return value != null ? value : defaultValue;
107	    }
108	}
