139	import com.pousadamarealta.service.exceptions.InvalidRequestException;
140	import io.javalin.http.Context;
141	
142	import java.time.LocalDate;
143	import java.time.YearMonth;
144	import java.time.format.DateTimeParseException;
145	
146	public class ReportHandler {
147	    private final OccupancyReport occupancyReport;
148	    private final RevenueReport revenueReport;
149	
150	    public ReportHandler(OccupancyReport occupancyReport, RevenueReport revenueReport) {
151	        this.occupancyReport = occupancyReport;
152	        this.revenueReport = revenueReport;
153	    }
154	
155	    public void getOccupancyReport(Context ctx) {
156	        try {
157	            String dateParam = ctx.queryParam("date");
158	            if (dateParam == null || dateParam.isBlank()) {
159	                throw new InvalidRequestException("Date parameter is required");
160	            }
161	
162	            LocalDate date = LocalDate.parse(dateParam);
163	            String csv = occupancyReport.generate(date);
164	
165	            ctx.contentType("text/csv; charset=utf-8")
166	               .result(csv);
167	
168	        } catch (DateTimeParseException e) {
169	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
170	        } catch (InvalidRequestException e) {
171	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
172	        }
173	    }
174	
175	    public void getRevenueReport(Context ctx) {
176	        try {
177	            String monthParam = ctx.queryParam("month");
178	            if (monthParam == null || monthParam.isBlank()) {
179	                throw new InvalidRequestException("Month parameter is required");
180	            }
181	
182	            YearMonth month = YearMonth.parse(monthParam);
183	            String csv = revenueReport.generate(month);
184	
185	            ctx.contentType("text/csv; charset=utf-8")
186	               .result(csv);
187	
188	        } catch (DateTimeParseException e) {
189	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
190	        } catch (InvalidRequestException e) {
191	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
192	        }
193	    }
194	}
195	package com.pousadamarealta.api.handler;
196	
197	import com.pousadamarealta.api.dto.CreateReservationRequest;
198	import com.pousadamarealta.api.dto.DocumentResponse;
199	import com.pousadamarealta.api.dto.ErrorResponse;
200	import com.pousadamarealta.api.dto.ReservationResponse;
201	import com.pousadamarealta.api.mapper.ApiMapper;
202	import com.pousadamarealta.database.RoomDao;
203	import com.pousadamarealta.domain.RatePlan;
204	import com.pousadamarealta.domain.Reservation;
205	import com.pousadamarealta.domain.ReservationStatus;
206	import com.pousadamarealta.service.ReservationService;
207	import com.pousadamarealta.service.exceptions.*;
208	import io.javalin.http.Context;
209	
210	import java.time.LocalDate;
211	import java.time.format.DateTimeParseException;
212	
213	public class ReservationHandler {
214	    private final ReservationService reservationService;
215	    private final RoomDao roomDao;
216	
217	    public ReservationHandler(ReservationService reservationService, RoomDao roomDao) {
218	        this.reservationService = reservationService;
219	        this.roomDao = roomDao;
220	    }
221	
222	    public void createReservation(Context ctx) {
223	        try {
224	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
225	
226	            validateRequest(request);
227	
228	            LocalDate checkIn = LocalDate.parse(request.checkIn());
229	            LocalDate checkOut = LocalDate.parse(request.checkOut());
230	            RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
231	
232	            Reservation reservation = reservationService.createReservation(
233	                request.roomNumber(),
234	                request.guestName(),
235	                request.guestEmail(),
236	                request.guestCpf(),
237	                checkIn,
238	                checkOut,
239	                request.guests(),
240	                ratePlan
241	            );
242	
243	            ctx.status(201).json(ApiMapper.toReservationResponse(reservation));
244	
245	        } catch (InvalidRequestException e) {
246	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
247	        } catch (RoomNotFoundException e) {
248	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
249	        } catch (RoomUnavailableException e) {
250	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
251	        } catch (CapacityExceededException e) {
252	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
253	        }
254	    }
255	
256	    public void getReservation(Context ctx) {
257	        try {
258	            long id = Long.parseLong(ctx.pathParam("id"));
259	            Reservation reservation = reservationService.getReservation(id);
260	            ctx.json(ApiMapper.toReservationResponse(reservation));
261	
262	        } catch (ReservationNotFoundException e) {
263	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
264	        }
265	    }
266	
267	    public void confirmReservation(Context ctx) {
268	        try {
269	            long id = Long.parseLong(ctx.pathParam("id"));
270	            Reservation reservation = reservationService.confirmReservation(id);
271	            ctx.json(ApiMapper.toReservationResponse(reservation));
272	
273	        } catch (ReservationNotFoundException e) {
274	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
275	        } catch (OperationNotAllowedException e) {
276	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
277	        }
278	    }
279	
280	    public void checkIn(Context ctx) {
281	        try {
282	            long id = Long.parseLong(ctx.pathParam("id"));
283	            Reservation reservation = reservationService.checkIn(id);
284	            ctx.json(ApiMapper.toReservationResponse(reservation));
285	
286	        } catch (ReservationNotFoundException e) {
287	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
288	        } catch (OperationNotAllowedException e) {
289	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
290	        }
291	    }
292	
293	    public void checkOut(Context ctx) {
294	        try {
295	            long id = Long.parseLong(ctx.pathParam("id"));
296	            Reservation reservation = reservationService.checkOut(id);
297	            DocumentResponse document = ApiMapper.toDocumentResponse(reservation, roomDao);
298	            ctx.json(document);
299	
300	        } catch (ReservationNotFoundException e) {
301	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
302	        } catch (OperationNotAllowedException e) {
303	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
304	        }
305	    }
306	
307	    public void cancelReservation(Context ctx) {
308	        try {
309	            long id = Long.parseLong(ctx.pathParam("id"));
310	            Reservation reservation = reservationService.cancelReservation(id);
311	            ctx.json(ApiMapper.toReservationResponse(reservation));
312	
313	        } catch (ReservationNotFoundException e) {
314	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
315	        } catch (OperationNotAllowedException e) {
316	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
317	        }
318	    }
319	
320	    public void getDocument(Context ctx) {
321	        try {
322	            long id = Long.parseLong(ctx.pathParam("id"));
323	            Reservation reservation = reservationService.getReservation(id);
324	
325	            if (reservation.getStatus() == ReservationStatus.PENDING) {
326	                throw new OperationNotAllowedException("Document only available for paid reservations");
327	            }
328	
329	            DocumentResponse document = ApiMapper.toDocumentResponse(reservation, roomDao);
330	            ctx.json(document);
331	
332	        } catch (ReservationNotFoundException e) {
333	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
334	        } catch (OperationNotAllowedException e) {
335	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
336	        }
337	    }
338	
339	    private void validateRequest(CreateReservationRequest request) {
340	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
341	            throw new InvalidRequestException("Room number is required");
342	        }
343	        if (request.guestName() == null || request.guestName().isBlank()) {
344	            throw new InvalidRequestException("Guest name is required");
345	        }
346	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
347	            throw new InvalidRequestException("Guest email is required");
348	        }
349	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
350	            throw new InvalidRequestException("Guest CPF is required");
351	        }
352	        if (request.checkIn() == null || request.checkIn().isBlank()) {
353	            throw new InvalidRequestException("Check-in date is required");
354	        }
355	        if (request.checkOut() == null || request.checkOut().isBlank()) {
356	            throw new InvalidRequestException("Check-out date is required");
357	        }
358	        if (request.guests() == null) {
359	            throw new InvalidRequestException("Number of guests is required");
360	        }
361	        if (request.ratePlan() == null || request.ratePlan().isBlank()) {
362	            throw new InvalidRequestException("Rate plan is required");
363	        }
364	
365	        try {
366	            LocalDate.parse(request.checkIn());
367	        } catch (DateTimeParseException e) {
368	            throw new InvalidRequestException("Invalid check-in date format");
369	        }
370	
371	        try {
372	            LocalDate.parse(request.checkOut());
373	        } catch (DateTimeParseException e) {
374	            throw new InvalidRequestException("Invalid check-out date format");
375	        }
376	
377	        try {
378	            RatePlan.valueOf(request.ratePlan());
379	        } catch (IllegalArgumentException e) {
380	            throw new InvalidRequestException("Invalid rate plan");
381	        }
382	    }
383	}
