409	package com.pousadamarealta.api.mapper;
410	
411	import com.pousadamarealta.api.dto.*;
412	import com.pousadamarealta.database.RoomDao;
413	import com.pousadamarealta.domain.Message;
414	import com.pousadamarealta.domain.Reservation;
415	import com.pousadamarealta.domain.Room;
416	
417	import java.time.format.DateTimeFormatter;
418	
419	public class ApiMapper {
420	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
421	
422	    public static RoomResponse toRoomResponse(Room room) {
423	        return new RoomResponse(
424	            room.getNumber(),
425	            room.getType().name(),
426	            room.getCapacity(),
427	            room.getNightlyRate().doubleValue()
428	        );
429	    }
430	
431	    public static ReservationResponse toReservationResponse(Reservation reservation) {
432	        return new ReservationResponse(
433	            reservation.getId(),
434	            reservation.getRoomNumber(),
435	            reservation.getGuestName(),
436	            reservation.getGuestEmail(),
437	            reservation.getGuestCpf(),
438	            reservation.getCheckIn().format(DATE_FORMATTER),
439	            reservation.getCheckOut().format(DATE_FORMATTER),
440	            reservation.getGuests(),
441	            reservation.getRatePlan().name(),
442	            reservation.getNights(),
443	            reservation.getSubtotal().doubleValue(),
444	            reservation.getDiscount().doubleValue(),
445	            reservation.getTotal().doubleValue(),
446	            reservation.getStatus().name(),
447	            reservation.getAmountPaid().doubleValue(),
448	            reservation.getRefund() != null ? reservation.getRefund().doubleValue() : null
449	        );
450	    }
451	
452	    public static DocumentResponse toDocumentResponse(Reservation reservation, RoomDao roomDao) {
453	        Room room = roomDao.findByNumber(reservation.getRoomNumber()).orElseThrow();
454	        DateTimeFormatter displayFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
455	
456	        return new DocumentResponse(
457	            "Comprovante de reserva",
458	            reservation.getId(),
459	            reservation.getGuestName(),
460	            reservation.getGuestCpf(),
461	            reservation.getRoomNumber(),
462	            room.getType().name(),
463	            reservation.getCheckIn().format(displayFormatter),
464	            reservation.getCheckOut().format(displayFormatter),
465	            reservation.getNights(),
466	            reservation.getSubtotal().doubleValue(),
467	            reservation.getDiscount().doubleValue(),
468	            reservation.getTotal().doubleValue()
469	        );
470	    }
471	
472	    public static MessageResponse toMessageResponse(Message message) {
473	        return new MessageResponse(
474	            message.getId(),
475	            message.getChannel().name(),
476	            message.getTo(),
477	            message.getSubject(),
478	            message.getBody(),
479	            message.getStatus().name()
480	        );
481	    }
482	}

