 19	
 20	    public void send(String to, String subject, String body) {
 21	        OutgoingMessage outgoing = new OutgoingMessage(MessageChannel.EMAIL, to, subject, body);
 22	        List<OutgoingMessage> processedMessages = pipeline.process(outgoing);
 23	
 24	        for (OutgoingMessage msg : processedMessages) {
 25	            Message message = new Message(
 26	                null,
