142	import com.pousadamarealta.database.ReservationDao;
143	import com.pousadamarealta.database.RoomDao;
144	import com.pousadamarealta.domain.*;
145	import com.pousadamarealta.service.exceptions.*;
146	
147	import java.math.BigDecimal;
148	import java.time.LocalDate;
149	import java.time.format.DateTimeFormatter;
150	
151	public class ReservationService {
152	    private final ReservationDao reservationDao;
153	    private final RoomDao roomDao;
154	    private final PricingCalculator pricingCalculator;
155	    private final MessageService messageService;
156	
157	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
158	
159	    public ReservationService(ReservationDao reservationDao, RoomDao roomDao,
160	                            PricingCalculator pricingCalculator, MessageService messageService) {
161	        this.reservationDao = reservationDao;
162	        this.roomDao = roomDao;
163	        this.pricingCalculator = pricingCalculator;
164	        this.messageService = messageService;
165	    }
166	
167	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
168	                                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
169	
170	        Room room = roomDao.findByNumber(roomNumber)
171	            .orElseThrow(() -> new RoomNotFoundException("Room " + roomNumber + " not found"));
172	
173	        if (guests < 1) {
174	            throw new InvalidRequestException("At least one guest is required");
175	        }
176	
177	        if (guests > room.getCapacity()) {
178	            throw new CapacityExceededException("Room " + roomNumber + " has capacity for " +
179	                room.getCapacity() + " guests, but " + guests + " were requested");
180	        }
181	
182	        if (!checkOut.isAfter(checkIn)) {
183	            throw new InvalidRequestException("Check-out date must be after check-in date");
184	        }
185	
186	        if (reservationDao.hasConflict(roomNumber, checkIn, checkOut, null)) {
187	            throw new RoomUnavailableException("Room " + roomNumber + " is not available for the requested dates");
188	        }
189	
190	        PricingCalculator.PricingResult pricing = pricingCalculator.calculate(
191	            room.getType(), checkIn, checkOut, ratePlan);
192	
193	        Reservation reservation = new Reservation(
194	            null,
195	            roomNumber,
196	            guestName,
197	            guestEmail,
198	            guestCpf,
199	            checkIn,
200	            checkOut,
201	            guests,
202	            ratePlan,
203	            pricing.getNights(),
204	            pricing.getSubtotal(),
205	            pricing.getDiscount(),
206	            pricing.getTotal(),
207	            ReservationStatus.PENDING,
208	            BigDecimal.ZERO,
209	            null
210	        );
211	
212	        return reservationDao.create(reservation);
213	    }
214	
215	    public Reservation confirmReservation(Long id) {
216	        Reservation reservation = reservationDao.findById(id)
217	            .orElseThrow(() -> new ReservationNotFoundException("Reservation " + id + " not found"));
218	
219	        if (!reservation.canConfirm()) {
220	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
221	        }
222	
223	        reservation.setStatus(ReservationStatus.CONFIRMED);
224	        reservation.setAmountPaid(reservation.getTotal());
225	        reservationDao.update(reservation);
226	
227	        sendConfirmationEmail(reservation);
228	
229	        return reservation;
230	    }
231	
232	    public Reservation checkIn(Long id) {
233	        Reservation reservation = reservationDao.findById(id)
234	            .orElseThrow(() -> new ReservationNotFoundException("Reservation " + id + " not found"));
235	
236	        if (!reservation.canCheckIn()) {
237	            throw new OperationNotAllowedException("Cannot check in reservation in status " + reservation.getStatus());
238	        }
239	
240	        reservation.setStatus(ReservationStatus.CHECKED_IN);
241	        reservationDao.update(reservation);
242	
243	        return reservation;
244	    }
245	
246	    public Reservation checkOut(Long id) {
247	        Reservation reservation = reservationDao.findById(id)
248	            .orElseThrow(() -> new ReservationNotFoundException("Reservation " + id + " not found"));
249	
250	        if (!reservation.canCheckOut()) {
251	            throw new OperationNotAllowedException("Cannot check out reservation in status " + reservation.getStatus());
252	        }
253	
254	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
255	        reservationDao.update(reservation);
256	
257	        return reservation;
258	    }
259	
260	    public Reservation cancelReservation(Long id) {
261	        Reservation reservation = reservationDao.findById(id)
262	            .orElseThrow(() -> new ReservationNotFoundException("Reservation " + id + " not found"));
263	
264	        if (!reservation.canCancel()) {
265	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.getStatus());
266	        }
267	
268	        BigDecimal refundAmount = calculateRefund(reservation);
269	
270	        reservation.setStatus(ReservationStatus.CANCELLED);
271	        reservation.setRefund(refundAmount);
272	        reservationDao.update(reservation);
273	
