 42	
 43	import com.pousadamarealta.domain.RatePlan;
 44	import com.pousadamarealta.domain.RoomType;
 45	
 46	import java.math.BigDecimal;
 47	import java.math.RoundingMode;
 48	import java.time.LocalDate;
 49	import java.time.Month;
 50	
 51	public class PricingCalculator {
 52	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 53	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
 54	
 55	    public static class PricingResult {
 56	        private final int nights;
 57	        private final BigDecimal subtotal;
 58	        private final BigDecimal discount;
 59	        private final BigDecimal total;
 60	
 61	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
 62	            this.nights = nights;
 63	            this.subtotal = subtotal;
 64	            this.discount = discount;
 65	            this.total = total;
 66	        }
 67	
 68	        public int getNights() {
 69	            return nights;
 70	        }
 71	
 72	        public BigDecimal getSubtotal() {
 73	            return subtotal;
 74	        }
 75	
 76	        public BigDecimal getDiscount() {
 77	            return discount;
 78	        }
 79	
 80	        public BigDecimal getTotal() {
 81	            return total;
 82	        }
 83	    }
 84	
 85	    public PricingResult calculate(RoomType roomType, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 86	        int nights = (int) checkIn.until(checkOut).getDays();
 87	
 88	        BigDecimal subtotal = BigDecimal.ZERO;
 89	        LocalDate currentDate = checkIn;
 90	
 91	        for (int i = 0; i < nights; i++) {
 92	            BigDecimal nightRate = calculateNightRate(roomType, currentDate);
 93	            subtotal = subtotal.add(nightRate);
 94	            currentDate = currentDate.plusDays(1);
 95	        }
 96	
 97	        subtotal = round(subtotal);
 98	
 99	        BigDecimal discount = BigDecimal.ZERO;
100	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
101	            discount = round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
102	        }
103	
104	        BigDecimal total = round(subtotal.subtract(discount));
105	
106	        return new PricingResult(nights, subtotal, discount, total);
107	    }
108	
109	    private BigDecimal calculateNightRate(RoomType roomType, LocalDate date) {
110	        BigDecimal baseRate = roomType.getNightlyRate();
111	        if (isHighSeason(date)) {
112	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
113	        }
114	        return baseRate;
115	    }
116	
117	    private boolean isHighSeason(LocalDate date) {
118	        Month month = date.getMonth();
119	        int day = date.getDayOfMonth();
120	
121	        if (month == Month.DECEMBER && day >= 15) {
122	            return true;
123	        }
124	
125	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
126	            return true;
127	        }
128	
129	        if (month == Month.JULY) {
130	            return true;
131	        }
132	
133	        return false;
134	    }
135	
136	    private BigDecimal round(BigDecimal value) {
137	        return value.setScale(2, RoundingMode.HALF_EVEN);
138	    }
139	}
