132	public class ArchiveCopyRule implements MessageRule {
133	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
134	    private static final String SUBJECT_PREFIX = "[Cópia] ";
135	
136	    @Override
137	    public void process(MessageContext context) {
138	        if (!context.isBlocked()) {
139	            OutgoingMessage original = context.getMessage();
140	            OutgoingMessage copy = original.copy(
141	                ARCHIVE_EMAIL,
