 50	        for (MessageRule rule : rules) {
 51	            rule.process(context);
 52	        }
 53	
 54	        List<OutgoingMessage> result = new ArrayList<>();
 55	        result.add(context.getMessage());
 56	        result.addAll(context.getAdditionalMessages());
 57	
 58	        return result;
 59	    }
 60	}
