153	
154	public class EmailValidationRule implements MessageRule {
155	    @Override
156	    public void process(MessageContext context) {
157	        String email = context.getMessage().getTo();
158	        if (!isValidEmail(email)) {
159	            context.getMessage().block();
160	        }
161	    }
162	
163	    private boolean isValidEmail(String email) {
164	        if (email == null || email.isEmpty()) {
165	            return false;
166	        }
167	
168	        int atIndex = email.indexOf('@');
169	        if (atIndex <= 0) {
170	            return false;
171	        }
172	
173	        if (email.lastIndexOf('@') != atIndex) {
174	            return false;
175	        }
176	
177	        String domain = email.substring(atIndex + 1);
178	        return !domain.isEmpty() && domain.contains(".");
179	    }
180	}
