  1	package com.pousadamarealta;
  2	
  3	import com.pousadamarealta.domain.MessageChannel;
  4	import com.pousadamarealta.domain.MessageStatus;
  5	import com.pousadamarealta.messaging.MessagePipeline;
  6	import com.pousadamarealta.messaging.MessageRule;
  7	import com.pousadamarealta.messaging.OutgoingMessage;
  8	import com.pousadamarealta.messaging.rules.ArchiveCopyRule;
  9	import com.pousadamarealta.messaging.rules.EmailValidationRule;
 10	import com.pousadamarealta.messaging.rules.TestModeRedirectRule;
 11	import org.junit.jupiter.api.Test;
 12	
 13	import java.util.ArrayList;
 14	import java.util.List;
 15	
 16	import static org.junit.jupiter.api.Assertions.*;
 17	
 18	public class MessagePipelineTest {
 19	
 20	    @Test
 21	    void testEmailValidationBlocked() {
 22	        List<MessageRule> rules = new ArrayList<>();
 23	        rules.add(new EmailValidationRule());
 24	        MessagePipeline pipeline = new MessagePipeline(rules);
 25	
 26	        OutgoingMessage message = new OutgoingMessage(
 27	            MessageChannel.EMAIL,
 28	            "invalid.email",
 29	            "Subject",
 30	            "Body"
 31	        );
 32	
 33	        List<OutgoingMessage> result = pipeline.process(message);
 34	
 35	        assertEquals(1, result.size());
 36	        assertEquals(MessageStatus.BLOCKED, result.get(0).getStatus());
 37	        assertEquals("invalid.email", result.get(0).getTo());
 38	    }
 39	
 40	    @Test
 41	    void testEmailValidationPassed() {
 42	        List<MessageRule> rules = new ArrayList<>();
 43	        rules.add(new EmailValidationRule());
 44	        MessagePipeline pipeline = new MessagePipeline(rules);
 45	
 46	        OutgoingMessage message = new OutgoingMessage(
 47	            MessageChannel.EMAIL,
 48	            "valid@example.com",
 49	            "Subject",
 50	            "Body"
 51	        );
 52	
 53	        List<OutgoingMessage> result = pipeline.process(message);
 54	
 55	        assertEquals(1, result.size());
 56	        assertEquals(MessageStatus.SENT, result.get(0).getStatus());
 57	    }
 58	
 59	    @Test
 60	    void testArchiveCopyRule() {
 61	        List<MessageRule> rules = new ArrayList<>();
 62	        rules.add(new EmailValidationRule());
 63	        rules.add(new ArchiveCopyRule());
 64	        MessagePipeline pipeline = new MessagePipeline(rules);
 65	
 66	        OutgoingMessage message = new OutgoingMessage(
 67	            MessageChannel.EMAIL,
 68	            "user@example.com",
 69	            "Test Subject",
 70	            "Test Body"
 71	        );
 72	
 73	        List<OutgoingMessage> result = pipeline.process(message);
 74	
 75	        assertEquals(2, result.size());
 76	
 77	        assertEquals("user@example.com", result.get(0).getTo());
 78	        assertEquals("Test Subject", result.get(0).getSubject());
 79	        assertEquals(MessageStatus.SENT, result.get(0).getStatus());
 80	
 81	        assertEquals("arquivo@pousadamarealta.com.br", result.get(1).getTo());
 82	        assertEquals("[Cópia] Test Subject", result.get(1).getSubject());
 83	        assertEquals("Test Body", result.get(1).getBody());
 84	        assertEquals(MessageStatus.SENT, result.get(1).getStatus());
 85	    }
 86	
 87	    @Test
 88	    void testArchiveCopyNotCreatedForBlockedMessage() {
 89	        List<MessageRule> rules = new ArrayList<>();
 90	        rules.add(new EmailValidationRule());
 91	        rules.add(new ArchiveCopyRule());
 92	        MessagePipeline pipeline = new MessagePipeline(rules);
 93	
 94	        OutgoingMessage message = new OutgoingMessage(
 95	            MessageChannel.EMAIL,
 96	            "invalid",
 97	            "Subject",
 98	            "Body"
 99	        );
100	
101	        List<OutgoingMessage> result = pipeline.process(message);
102	
103	        assertEquals(1, result.size());
104	        assertEquals(MessageStatus.BLOCKED, result.get(0).getStatus());
105	    }
106	
107	    @Test
108	    void testTestModeRedirect() {
109	        List<MessageRule> rules = new ArrayList<>();
110	        rules.add(new EmailValidationRule());
111	        rules.add(new TestModeRedirectRule());
112	        MessagePipeline pipeline = new MessagePipeline(rules);
113	
114	        OutgoingMessage message = new OutgoingMessage(
115	            MessageChannel.EMAIL,
116	            "original@example.com",
117	            "Original Subject",
118	            "Original Body"
119	        );
120	
121	        List<OutgoingMessage> result = pipeline.process(message);
122	
123	        assertEquals(1, result.size());
124	        assertEquals("testes@pousadamarealta.com.br", result.get(0).getTo());
125	        assertEquals("[TESTE] Original Subject", result.get(0).getSubject());
126	        assertTrue(result.get(0).getBody().startsWith("Destinatário original: original@example.com\n"));
127	        assertTrue(result.get(0).getBody().contains("Original Body"));
128	        assertEquals(MessageStatus.SENT, result.get(0).getStatus());
129	    }
130	
131	    @Test
132	    void testTestModeDoesNotRedirectBlockedMessage() {
133	        List<MessageRule> rules = new ArrayList<>();
134	        rules.add(new EmailValidationRule());
135	        rules.add(new TestModeRedirectRule());
136	        MessagePipeline pipeline = new MessagePipeline(rules);
137	
138	        OutgoingMessage message = new OutgoingMessage(
139	            MessageChannel.EMAIL,
140	            "invalid.email",
141	            "Subject",
142	            "Body"
143	        );
